DROP VIEW IF EXISTS `Sales_vStoreWithAddresses`;
CREATE VIEW `Sales_vStoreWithAddresses` AS
select `s`.`BusinessEntityID` AS `BusinessEntityID`,`s`.`Name` AS `Name`,`at`.`Name` AS `AddressType`,`a`.`AddressLine1` AS `AddressLine1`,`a`.`AddressLine2` AS `AddressLine2`,`a`.`City` AS `City`,`sp`.`Name` AS `StateProvinceName`,`a`.`PostalCode` AS `PostalCode`,`cr`.`Name` AS `CountryRegionName` from (((((`adventureworks`.`Sales_Store` `s` join `adventureworks`.`Person_BusinessEntityAddress` `bea` on((`bea`.`BusinessEntityID` = `s`.`BusinessEntityID`))) join `adventureworks`.`Person_Address` `a` on((`a`.`AddressID` = `bea`.`AddressID`))) join `adventureworks`.`Person_StateProvince` `sp` on((`sp`.`StateProvinceID` = `a`.`StateProvinceID`))) join `adventureworks`.`Person_CountryRegion` `cr` on((`cr`.`CountryRegionCode` = `sp`.`CountryRegionCode`))) join `adventureworks`.`Person_AddressType` `at` on((`at`.`AddressTypeID` = `bea`.`AddressTypeID`)))